            "actividad": "Consulta Ingreso Equipo de Salud Mental",
            "horas": 1.0,
            "rendimiento": 1.0,
            "prod1Sem": 7.0,
            "prod2Sem": 11.0,
            "rr": "R",
            "tipo": "C",
