// Helper: buscar glosario por nombre de actividad (búsqueda flexible)
export function findGlosa(actividadNombre) {
  if (!actividadNombre) return null;
  const norm = actividadNombre.toLowerCase().trim();
  return glosario.find(g => 
    g.actPlanilla && g.actPlanilla.toLowerCase().trim() === norm
  ) || glosario.find(g =>
    g.actMinsal && g.actMinsal.toLowerCase().trim() === norm
  ) || null;
}
